const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([140.468626, -45.432798]);
  const region = point.buffer(100000); // 100km radius

  // Time periods for comparison
  const period1_start = '2018-11-01';
  const period1_end = '2019-02-28';
  const period2_start = '2019-11-01';
  const period2_end = '2020-02-29';

  // 2. Data Acquisition - MODIS Ocean Color for chlorophyll
  const getChlorophyllData = function(startDate, endDate) {
    return ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
      .filterDate(startDate, endDate)
      .filterBounds(region)
      .select('chlor_a');
  };

  const col1 = getChlorophyllData(period1_start, period1_end);
  const col2 = getChlorophyllData(period2_start, period2_end);

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Period 1 (2018-2019) Images: ${size1}`);
  console.log(`Period 2 (2019-2020) Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create mean composites for each period
  const mean1 = col1.mean();
  const mean2 = col2.mean();

  // Calculate mean chlorophyll concentration for each period
  const stats1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const chlor1 = stats1.chlor_a;
  const chlor2 = stats2.chlor_a;

  // Check for valid results
  if (chlor1 === null || chlor2 === null || 
      isNaN(chlor1) || isNaN(chlor2) ||
      chlor1 === undefined || chlor2 === undefined) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate pixel counts to ensure valid data
  const count1 = mean1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo().chlor_a;

  const count2 = mean2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo().chlor_a;

  console.log(`2018-2019 Chl-a: ${chlor1?.toFixed(4)} mg/m³, Pixels: ${count1}`);
  console.log(`2019-2020 Chl-a: ${chlor2?.toFixed(4)} mg/m³, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Determine if concentrations were "up" in the later period
  const difference = chlor2 - chlor1;
  const percentChange = ((difference / chlor1) * 100);

  console.log(`Change: ${difference.toFixed(4)} mg/m³ (${percentChange.toFixed(1)}%)`);

  // Final decision - if 2019-2020 is higher than 2018-2019
  if (chlor2 > chlor1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
